<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Branch,Company,SalesOrder,SalesOrderItem,SalesReturn,SalesReturnItem,WarehouseLocation}; use App\Services\{AuthorizationService,SalesNumberService,StockMovementService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class SalesReturnController {
 private function tenant():string{return app(TenantContext::class)->id();}
 private function authorize(Request $r,?SalesOrder $order=null):void{$t=$this->tenant();abort_unless($r->user()&&app(AuthorizationService::class)->allows($r->user(),$t,'sales.manage',$order?->company_id,$order?->branch_id),403);if($order)abort_unless($order->tenant_id===$t,404);}
 private function query(Request $r){$q=SalesReturn::where('tenant_id',$this->tenant())->with(['salesOrder.customer','items.orderItem.variant.product','items.location'])->latest('created_at');if($r->filled('state'))$q->where('state',$r->string('state'));if($r->filled('customer_id'))$q->whereHas('salesOrder',fn($x)=>$x->where('customer_id',$r->string('customer_id')));if($r->filled('company_id'))$q->whereHas('salesOrder',fn($x)=>$x->where('company_id',$r->string('company_id')));if($r->filled('branch_id'))$q->whereHas('salesOrder',fn($x)=>$x->where('branch_id',$r->string('branch_id')));if($r->filled('search'))$q->where(fn($x)=>$x->where('number','ilike','%'.$r->string('search').'%')->orWhereHas('salesOrder',fn($o)=>$o->where('number','ilike','%'.$r->string('search').'%')->orWhereHas('customer',fn($c)=>$c->where('name','ilike','%'.$r->string('search').'%'))));if($r->filled('date_from'))$q->whereDate('created_at','>=',$r->date('date_from'));if($r->filled('date_to'))$q->whereDate('created_at','<=',$r->date('date_to'));return $q;}
 public function index(Request $r){$this->authorize($r);$q=$this->query($r);return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100)),'summary'=>['total'=>(clone $q)->count(),'draft'=>(clone $q)->where('state','draft')->count(),'received'=>(clone $q)->where('state','received')->count()]]);}
 public function show(Request $r,SalesReturn $return){abort_unless($return->tenant_id===$this->tenant(),404);$this->authorize($r,$return->salesOrder);return response()->json(['data'=>$return->load(['salesOrder.customer','items.orderItem.variant.product','items.location'])]);}
 public function store(Request $r,SalesNumberService $numbers){$t=$this->tenant();$this->authorize($r);$d=$r->validate(['sales_order_id'=>'required|uuid','idempotency_key'=>'required|string|max:100','items'=>'required|array|min:1','items.*.sales_order_item_id'=>'required|uuid','items.*.location_id'=>'required|uuid','items.*.quantity'=>['required','regex:/^\d+(\.\d{1,6})?$/','gt:0']]);$order=SalesOrder::where('tenant_id',$t)->whereKey($d['sales_order_id'])->with('items')->firstOrFail();$this->authorize($r,$order);if($existing=SalesReturn::where('tenant_id',$t)->where('idempotency_key',$d['idempotency_key'])->first())return response()->json(['data'=>$existing->load('items')]);foreach($d['items'] as $line){$item=$order->items->firstWhere('id',$line['sales_order_item_id']);abort_unless($item,422,'Return item does not belong to the selected sales order.');abort_unless(WarehouseLocation::where('tenant_id',$t)->whereKey($line['location_id'])->exists(),422,'Return location is unavailable.');$available=Decimal::sub((string)$item->delivered_quantity,(string)$item->returned_quantity);abort_unless(Decimal::compare((string)$line['quantity'],$available)<=0,422,'Return exceeds delivered quantity.');}$ret=DB::transaction(function()use($d,$order,$r,$numbers,$t){$ret=SalesReturn::create(['tenant_id'=>$t,'sales_order_id'=>$order->id,'created_by'=>$r->user()->id,'number'=>$numbers->next($t,'return'),'state'=>'draft','idempotency_key'=>$d['idempotency_key']]);foreach($d['items'] as $line)SalesReturnItem::create(['tenant_id'=>$t,'sales_return_id'=>$ret->id,'sales_order_item_id'=>$line['sales_order_item_id'],'location_id'=>$line['location_id'],'quantity'=>Decimal::normalize((string)$line['quantity'])]);return $ret;});return response()->json(['data'=>$ret->load('items')],201);}
 public function receive(Request $r,SalesReturn $return,StockMovementService $movements){abort_unless($return->tenant_id===$this->tenant(),404);$this->authorize($r,$return->salesOrder);$ret=DB::transaction(function()use($return,$r,$movements){$ret=SalesReturn::whereKey($return->id)->where('tenant_id',$this->tenant())->lockForUpdate()->firstOrFail();abort_unless($ret->state==='draft',422,'Only draft returns can be received.');$order=SalesOrder::whereKey($ret->sales_order_id)->where('tenant_id',$this->tenant())->firstOrFail();foreach($ret->items()->lockForUpdate()->get() as $line){$item=SalesOrderItem::whereKey($line->sales_order_item_id)->where('sales_order_id',$order->id)->lockForUpdate()->firstOrFail();$available=Decimal::sub((string)$item->delivered_quantity,(string)$item->returned_quantity);abort_unless(Decimal::compare((string)$line->quantity,$available)<=0,422,'Return exceeds the remaining delivered quantity.');$movements->post(['tenant_id'=>$this->tenant(),'variant_id'=>$item->variant_id,'location_id'=>$line->location_id,'created_by'=>$r->user()->id,'movement_type'=>'sale_return','quantity'=>$line->quantity,'unit_cost'=>'0','reference_type'=>'sales_return','reference_id'=>$ret->id,'idempotency_key'=>'sales-return:'.$ret->id.':'.$line->id]);$item->update(['returned_quantity'=>Decimal::add((string)$item->returned_quantity,(string)$line->quantity)]);} $ret->update(['state'=>'received']);return $ret;});return response()->json(['data'=>$ret->load('items')]);}
 public function post(Request $r,SalesOrder $order,AuthorizationService $a,SalesNumberService $numbers,StockMovementService $movements){$t=$this->tenant();abort_unless($order->tenant_id===$t,404);abort_unless($a->allows($r->user(),$t,'sales.manage',$order->company_id,$order->branch_id),403);$d=$r->validate(['idempotency_key'=>'required|string|max:100','items'=>'required|array|min:1','items.*.sales_order_item_id'=>'required|uuid','items.*.location_id'=>'required|uuid','items.*.quantity'=>'required|numeric|min:0.000001']);if($existing=SalesReturn::where('tenant_id',$t)->where('idempotency_key',$d['idempotency_key'])->first())return response()->json(['data'=>$existing]);$ret=DB::transaction(function()use($d,$order,$r,$numbers,$movements,$t){$ret=SalesReturn::create(['tenant_id'=>$t,'sales_order_id'=>$order->id,'created_by'=>$r->user()->id,'number'=>$numbers->next($t,'return'),'state'=>'received','idempotency_key'=>$d['idempotency_key']]);foreach($d['items'] as $k=>$line){$item=SalesOrderItem::where('tenant_id',$t)->where('sales_order_id',$order->id)->whereKey($line['sales_order_item_id'])->lockForUpdate()->firstOrFail();$qty=Decimal::normalize((string)$line['quantity']);$available=Decimal::sub((string)$item->delivered_quantity,(string)$item->returned_quantity);if(Decimal::compare($qty,$available)>0)throw ValidationException::withMessages(['quantity'=>['Return exceeds delivered quantity.']]);SalesReturnItem::create(['tenant_id'=>$t,'sales_return_id'=>$ret->id,'sales_order_item_id'=>$item->id,'location_id'=>$line['location_id'],'quantity'=>$qty]);$movements->post(['tenant_id'=>$t,'variant_id'=>$item->variant_id,'location_id'=>$line['location_id'],'created_by'=>$r->user()->id,'movement_type'=>'sale_return','quantity'=>$qty,'unit_cost'=>'0','reference_type'=>'sales_return','reference_id'=>$ret->id,'idempotency_key'=>'sales-return:'.$ret->id.':'.$k]);$item->update(['returned_quantity'=>Decimal::add((string)$item->returned_quantity,$qty)]);}return $ret->load('items');});return response()->json(['data'=>$ret],201);}
}
